from pathlib import Path
import json,html
R=Path(__file__).parent;m=json.loads((R/'curadoria-20.json').read_text());e=html.escape
cards=[];audit=[]
for x in m['items']:
 src=x.get('source_file')
 pic=f'<img src="{e(src)}" alt="Candidata para {e(x["title"])}">' if src else '<div class="empty">Foto ainda em seleção</div>'
 cards.append(f'''<article><div class="number">{x['id']:02d} / {e(x['kind'])}</div>{pic}<h2>{e(x['title'])}</h2><p>{e(x['brief'])}</p><p class="note">{e(x['note'])}</p><small>{e(x['credit'])}</small><div class="links"><a href="{e(x['source'])}" target="_blank" rel="noopener">Ver fonte</a>{f'<a href="{e(src)}" target="_blank">Arquivo sem edição</a>' if src else ''}</div><span class="state">{e(x['status'])}</span></article>''')
 audit.append(f'<div><b>{x["id"]:02d} · {e(x["title"])}</b>{pic}</div>')
css='''*{box-sizing:border-box}body{margin:0;background:#f3f2e9;color:#081e16;font:16px/1.55 Arial,sans-serif}main{max-width:1400px;margin:auto;padding:32px}header{border-bottom:1px solid #bdc7bd;padding-bottom:24px;margin-bottom:24px}h1{font-size:44px;line-height:1.08;letter-spacing:-.04em;margin:20px 0}h2{font-size:21px;line-height:1.25;margin:16px 0}p{max-width:950px}a{color:inherit;text-underline-offset:4px}small{display:block;color:#456051}.rules{padding:22px;background:#081e16;color:#f3f2e9}.rules strong{color:#c8ff00}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:28px 22px;margin:32px 0}article{min-width:0;border-bottom:1px solid #bdc7bd;padding-bottom:20px}article img{width:100%;height:220px;object-fit:contain;background:#10291f;display:block}.number{font-size:12px;text-transform:uppercase;letter-spacing:.08em;margin-bottom:10px}.note{font-size:14px;color:#456051}.links{display:flex;gap:14px;flex-wrap:wrap;font-size:13px;margin:14px 0}.state{display:block;font-size:12px;background:#e0e7dc;padding:8px}.empty{height:220px;background:#e0e7dc;display:grid;place-items:center;color:#456051;text-align:center}.order{padding:20px 0;border-block:1px solid #bdc7bd}.fine{font-size:13px;color:#456051}nav{display:flex;gap:22px;flex-wrap:wrap}@media(max-width:1000px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:720px){main{padding:20px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}h1{font-size:36px}}@media(max-width:440px){.grid{grid-template-columns:1fr}}'''
order=' → '.join(e(next(x['title'].split(' · ')[0] for x in m['items'] if x['id']==n)) for n in m['proposed_order'])
body=f'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Curadoria · 20 personagens</title><style>{css}</style><main><header><nav><a href="index.html">← Direção visual e abertura</a><a href="curadoria-20.json">Registro da curadoria</a></nav><h1>Vinte personagens.<br>Gestos que ficam.</h1><p>Painel de pesquisa para revisão. As candidatas aparecem sem filtro e sem novos cortes, para avaliar rosto, mãos, bola e o espaço disponível. As pendências são registradas individualmente.</p></header><div class="rules"><strong>Critério atualizado</strong><p>Fotos de outras competições podem entrar, desde que o enquadramento não mostre elementos que remetam a elas. Romário e Edmundo no Mundial de 2000 estão aprovados. As legendas da abertura identificarão clube e época, sem atribuir cenas ao Brasileirão.</p></div><section class="order"><b>Ritmo proposto · 6 segundos por imagem</b><p>{order}</p><small>Alternar gesto, ação e cena coletiva sempre que o acervo permitir. Evitar o mesmo clube em imagens consecutivas.</small></section><div class="grid">{''.join(cards)}</div><p class="fine">Arquivos locais são cópias das versões publicadas, preservadas sem novos cortes ou filtros. Nem todas correspondem à matriz original da câmera. Crédito, contexto e condições de publicação continuam sendo verificados. Este painel é uma seleção de candidatas, não vinte fotos finais aprovadas.</p></main></html>'''
(R/'curadoria.html').write_text(body)
(R/'audit-fotos.html').write_text('<!doctype html><html><meta charset="utf-8"><style>body{font:14px Arial;background:#eee}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.grid>div{height:230px}.grid img{width:100%;height:200px;object-fit:contain;background:#15271e}.empty{height:200px;background:#ddd}</style><div class="grid">'+''.join(audit)+'</div></html>')
